    for (let k = 8; k >= 1; k--) {
        if (n >= a[k] && n % a[k] === 0) {
            console.log(a[k]);
            return;
        }
    }
}

class SHelper {
    constructor() {
        this.rl = null;
        this.data = [];
        this.index = 0;
    }

    async init() {
        this.rl = readline.createInterface({
            input: process.stdin,
            output: process.stdout,
            terminal: false
        });

        const self = this;
        this.rl.on('line', (line) => {
            self.data.push(...line.trim().split(/\s+/));
        });

        await new Promise((resolve) => {
            process.stdin.on('end', resolve);
        });
    }

    async readInt64() {
        while (this.index >= this.data.length) {
            await new Promise(resolve => setImmediate(resolve));
        }
        return parseInt(this.data[this.index++], 10);
    }
}

main();
